import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../styles/TransactionPages.css";

const MySales = () => {
  const [sales, setSales] = useState([]);
  const [totalEarnings, setTotalEarnings] = useState(0);
  const userId = sessionStorage.getItem("userId");

  useEffect(() => {
    if (userId) {
      fetch(`${API_BASE_URL}/api/sales/user/${userId}`)
        .then((res) => res.json())
        .then((data) => {
          setSales(data);
          const total = data.reduce((sum, item) => sum + parseFloat(item.price || 0), 0);
          setTotalEarnings(total);
        })
        .catch((err) => console.error("Error loading sales:", err));
    }
  }, [userId]);

  const toggleShipped = async (listingId) => {
    try {
      await fetch(`${API_BASE_URL}/api/listings/${listingId}/shipped`, {
        method: "PUT",
      });
      setSales((prev) =>
        prev.map((item) =>
          item.listing_id === listingId ? { ...item, shipped: true } : item
        )
      );
    } catch (err) {
      console.error("Error marking as shipped:", err);
    }
  };

  const handleEarlyPayout = () => {
    const confirmPayout = window.confirm("Payout now for a 3% early payout charge?");
    if (confirmPayout) {
      const fee = totalEarnings * 0.03;
      const finalPayout = totalEarnings - fee;

      alert(
        `✅ Payout Successful!\nTotal: $${totalEarnings.toFixed(2)}\nEarly Fee (3%): -$${fee.toFixed(
          2
        )}\nFinal Payout: $${finalPayout.toFixed(2)}`
      );

      setTotalEarnings(0);
      setSales([]);
    }
  };

  return (
    <div className="dashboard-wrapper">
      <Navbar />
      <main className="my-sales-container">
        <div className="earnings-summary-card">
          <h2>Total Earnings</h2>
          <p className={`earnings-amount ${totalEarnings < 0 ? "negative" : ""}`}>
            ${totalEarnings.toFixed(2)}
          </p>
          <p className="pay-info">Weekly payout every Friday</p>
          <button className="payout-now-btn" onClick={handleEarlyPayout}>
            💸 Payout Now
          </button>
        </div>

        <h2 className="section-heading">Items Sold</h2>
        <div className="sales-list">
          {sales.length === 0 ? (
            <p>No sales yet.</p>
          ) : (
            sales.map((item) => (
              <div key={item.id} className={`sales-item-card ${item.canceled ? "canceled" : ""}`}>
                <div className="sales-item-left">
                  <img
                    src={item.image || "/placeholder.jpg"}
                    alt={item.title}
                    className="sales-item-img"
                  />
                </div>
                <div className="sales-item-right">
                  <h3>{item.title || "Unnamed Item"}</h3>
                  <p>
                    <strong>Category:</strong> {item.category || "N/A"}
                  </p>
                  <p>
                    <strong>Price:</strong>{" "}
                    {item.price < 0
                      ? `- $${Math.abs(item.price).toFixed(2)}`
                      : `$${parseFloat(item.price).toFixed(2)}`}
                  </p>
                  {item.shipping_info && (
                    <p>
                      <strong>Ship To:</strong>{" "}
                      {item.shipping_info?.address1}, {item.shipping_info?.city},{" "}
                      {item.shipping_info?.state} {item.shipping_info?.zip},{" "}
                      {item.shipping_info?.country}
                    </p>
                  )}
                  <p>
                    <strong>Status:</strong>{" "}
                    {item.shipped ? "✅ Shipped" : "❌ Not Shipped"}
                  </p>

                  {item.canceled && <p className="cancel-tag">Canceled Order</p>}

                  {!item.shipped && !item.canceled && (
                    <button
                      className="mark-shipped-btn"
                      onClick={() => toggleShipped(item.listing_id)}
                    >
                      Mark as Shipped
                    </button>
                  )}
                </div>
              </div>
            ))
          )}
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default MySales;
